import { ChangeDetectionStrategy, Component, computed, input, model } from '@angular/core';
export interface AevkoCalendarDay {
  date: string;
  day: number;
  outside: boolean;
}
@Component({
  selector: 'aevko-calendar',
  standalone: true,
  templateUrl: './calendar.component.html',
  styleUrl: './calendar.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AevkoCalendar {
  readonly label = input('Choose a date');
  readonly month = model('2026-01');
  readonly value = model('');
  readonly min = input('');
  readonly max = input('');
  protected readonly weekdays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  protected readonly monthLabel = computed(() => {
    const [year, month] = this.parts();
    return new Intl.DateTimeFormat('en', {
      month: 'long',
      year: 'numeric',
      timeZone: 'UTC',
    }).format(new Date(Date.UTC(year, month - 1, 1)));
  });
  protected readonly days = computed<readonly AevkoCalendarDay[]>(() => {
    const [year, month] = this.parts();
    const first = new Date(Date.UTC(year, month - 1, 1));
    const start = new Date(first);
    start.setUTCDate(1 - first.getUTCDay());
    return Array.from({ length: 42 }, (_, index) => {
      const date = new Date(start);
      date.setUTCDate(start.getUTCDate() + index);
      return {
        date: date.toISOString().slice(0, 10),
        day: date.getUTCDate(),
        outside: date.getUTCMonth() !== month - 1,
      };
    });
  });
  protected changeMonth(offset: number): void {
    const [year, month] = this.parts();
    const date = new Date(Date.UTC(year, month - 1 + offset, 1));
    this.month.set(`${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`);
  }
  protected disabled(date: string): boolean {
    return (!!this.min() && date < this.min()) || (!!this.max() && date > this.max());
  }
  protected select(date: string): void {
    if (!this.disabled(date)) {
      this.value.set(date);
      this.month.set(date.slice(0, 7));
    }
  }
  protected move(event: KeyboardEvent, date: string): void {
    const offset =
      event.key === 'ArrowLeft'
        ? -1
        : event.key === 'ArrowRight'
          ? 1
          : event.key === 'ArrowUp'
            ? -7
            : event.key === 'ArrowDown'
              ? 7
              : 0;
    if (!offset) return;
    event.preventDefault();
    const next = new Date(`${date}T00:00:00Z`);
    next.setUTCDate(next.getUTCDate() + offset);
    const iso = next.toISOString().slice(0, 10);
    const grid = (event.currentTarget as HTMLElement).closest('[role="grid"]');
    this.select(iso);
    queueMicrotask(() => grid?.querySelector<HTMLElement>(`[data-aevko-date="${iso}"]`)?.focus());
  }
  private parts(): [number, number] {
    const [year, month] = this.month().split('-').map(Number);
    return [year || 2026, month || 1];
  }
}

:host {
  --cell-size: 2.5rem;
  border: 1px solid var(--aevko-border, #d4d4d4);
  display: inline-grid;
  padding: 0.75rem;
}
.header {
  align-items: center;
  display: grid;
  grid-template-columns: var(--cell-size) 1fr var(--cell-size);
  margin-block-end: 0.5rem;
  text-align: center;
}
button {
  background: transparent;
  border: 0;
  border-radius: 0;
  color: inherit;
  min-block-size: var(--cell-size);
  min-inline-size: var(--cell-size);
}
[role='row'] {
  display: grid;
  grid-template-columns: repeat(7, var(--cell-size));
}
.weekdays span {
  align-items: center;
  color: var(--aevko-muted-foreground, #666);
  display: flex;
  font-size: 0.75rem;
  justify-content: center;
}
[role='gridcell'][data-outside='true'] {
  color: var(--aevko-muted-foreground, #666);
}
[role='gridcell'][aria-selected='true'] {
  background: var(--aevko-foreground, #171717);
  color: var(--aevko-background, #fff);
}
button:hover:not(:disabled) {
  background: color-mix(in srgb, currentcolor 10%, transparent);
}
button:focus-visible {
  outline: 2px solid var(--aevko-ring, #a3a3a3);
  outline-offset: -2px;
}
button:disabled {
  opacity: 0.35;
}
@media (prefers-color-scheme: dark) {
  :host {
    --aevko-border: #404040;
    --aevko-muted: #2a2a2a;
    --aevko-foreground: #f5f5f5;
    --aevko-background: #171717;
    --aevko-muted-foreground: #a3a3a3;
    color: #f5f5f5;
  }
}
